import type { LighthouseReport } from '@blen/react-lighthouse-viewer';

export type LoadResult = { name: string; report: LighthouseReport } | { error: string };

export type SampleSummary = {
  slug: string;
  url: string;
  lighthouseVersion: string;
  fetchTime: string;
  scores: { id: string; title: string; score: number | null }[];
};

export const legacySlug = 'lighthouse-6';

const reportsUrl = `${import.meta.env.BASE_URL}reports/`;

// The sample reports are generated by `pnpm reports` (and on every Pages deploy), so they are
// always fresh runs of the bundled Lighthouse version.
export async function loadIndex(): Promise<SampleSummary[]> {
  const response = await fetch(`${reportsUrl}index.json`);
  return response.ok ? response.json() : [];
}

export async function loadSample(slug: string): Promise<LoadResult> {
  if (slug === legacySlug) return loadLegacy();
  const response = await fetch(`${reportsUrl}${encodeURIComponent(slug)}.json`);
  if (!response.ok) return { error: `There is no sample report named ${slug}.` };
  return toResult(slug, await response.json());
}

// A Lighthouse 6.1 report from 2020 (the package's test fixture). It shows that the renderer
// still reads old reports.
async function loadLegacy(): Promise<LoadResult> {
  const { default: report }: { default: unknown } =
    await import('../../packages/react-lighthouse-viewer/test/fixtures/lh-6.json');
  return toResult('Lighthouse 6 report', report);
}

export async function loadFile(file: File): Promise<LoadResult> {
  try {
    return toResult(file.name, JSON.parse(await file.text()));
  } catch {
    return { error: `${file.name} is not valid JSON.` };
  }
}

function toResult(name: string, report: unknown): LoadResult {
  return isReport(report)
    ? { name, report }
    : { error: `${name} is not a Lighthouse JSON report.` };
}

function isReport(value: unknown): value is LighthouseReport {
  return (
    typeof value === 'object' &&
    value !== null &&
    'lighthouseVersion' in value &&
    'categories' in value &&
    'audits' in value
  );
}
